// If no related articles exist, just return the original article (clean fields only)
return [
  {
    json: {
      url: $json.url,
      title: $json.title,
      description: $json.description,
      author: $json.author,
      publishedAt: $json.publishedAt,
      urlToImage: $json.urlToImage,
      source: $json.source,
      url_hash: $json.url_hash,
      check_get_url: $json.check_get_url,
      output: $json.output,
      article: $json.article

    }
  }
];

// items[0] = original article
// items[1..N] = related articles from Qdrant

const original = items[0].json;

// Grab related ones (they have `score`)
const related = items.slice(1).filter(i => i.json.score !== undefined);

// Flag: do we have any related?
const hasArticles = related.length > 0;

// Collect scores and preserve full related docs
const relatedScores = related.map(r => r.json.score);
const relatedArticles = related.map(r => r.json);

// Return the original article enriched with related info
return [
  {
    json: {
      ...original,
      hasArticles,
      relatedScores,
      relatedArticles
    }
  }
];

const scores = $json.relatedScores || [];
const matches = $json.relatedArticles || [];
const threshold = 0.80;

let hasHighScore = false;
let bestScore = null;
let bestMatch = null;

for (let i = 0; i < scores.length; i++) {
  const score = scores[i];
  if (score > threshold) {
    hasHighScore = true;
  }
  if (bestScore === null || score > bestScore) {
    bestScore = score;
    bestMatch = matches[i];
  }
}

return [
  {
    json: {
      url: $json.url,
      title: $json.title,
      description: $json.description,
      author: $json.author,
      publishedAt: $json.publishedAt,
      urlToImage: $json.urlToImage,
      source: $json.source,
      url_hash: $json.url_hash,
      check_get_url: $json.check_get_url,
      output: $json.output,
      article: $json.article,

      // Step 2 dedup info
      duplicate: hasHighScore,
      crossBatchScore: bestScore,
      crossBatchMatchedUrl: bestMatch?.document?.metadata?.url || null,
      crossBatchMatchedContent: bestMatch?.document?.pageContent || null
    }
  }
];

return [
  {
    json: {
      url: $json.url,
      title: $json.title,
      description: $json.description,
      author: $json.author,
      publishedAt: $json.publishedAt,
      urlToImage: $json.urlToImage,
      source: $json.source,
      url_hash: $json.url_hash,
      check_get_url: $json.check_get_url,
      output: $json.output,
      article: $json.article
    }
  }
];

if ($json.duplicate === true) {
  // send a minimal placeholder so loop continues
  return [{ json: { continue: true } }];
} else {
  // forward the unique item
  return [
    {
      json: {
        url: $json.url,
        title: $json.title,
        description: $json.description,
        author: $json.author,
        publishedAt: $json.publishedAt,
        urlToImage: $json.urlToImage,
        source: $json.source,
        url_hash: $json.url_hash,
        check_get_url: $json.check_get_url,
        output: $json.output,
        article: $json.article
      }
    }
  ];
}

function cosineSim(a, b) {
  let dot = 0.0, normA = 0.0, normB = 0.0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }
  return dot / (Math.sqrt(normA) * Math.sqrt(normB));
}

const threshold = 0.70; // tweak as needed
const deduped = [];
const results = [];

for (const item of items) {
  const emb = item.json.embedding;
  let isDup = false;
  let simScore = null;
  let matchUrl = null;
  let matchTitle = null;

  for (const kept of deduped) {
    const sim = cosineSim(emb, kept.json.embedding);
    if (sim > threshold) {
      isDup = true;
      simScore = sim;          // store score that triggered duplicate
      matchUrl = kept.json.url;
      matchTitle = kept.json.title;
      break;                   // keep your original "stop at first match"
    }
  }

  results.push({
    json: {
      ...item.json,
      duplicate: isDup,
      similarity: simScore,     // null if unique, number if dup
      matchedUrl: matchUrl,     // URL of the article it matched
      matchedTitle: matchTitle  // Title of the article it matched
    }
  });

  if (!isDup) {
    deduped.push(item);
  }
}

return results;

const title = ($json.title || '').replace(/\s+/g, ' ').trim();
const desc  = ($json.description || '').replace(/\s+/g, ' ').trim();

return {
  ...$json,
  textForEmbedding: `${title} ${desc}`
};

return {
  json: {
    url: $json.url,
    title: $json.title,
    description: $json.description,
    author: $json.author,
    publishedAt: $json.publishedAt,
    source: $json.source,
    url_hash: $json.url_hash,
    urlToImage:$json.urlToImage,
    check_get_url:$json.check_get_url ,
    output: $json.output,
    article: $json.article,
    from: $json.from,
    textForEmbedding: $json.textForEmbedding,
    embedding: $json.data[0].embedding // extract clean vector
  }
};

const embedding = $json.embedding;   // from OpenAI embeddings response
const now = Math.floor(Date.now() / 1000);   // current Unix timestamp
const cutoff = now - (48 * 60 * 60);
         // 12 hours ago in seconds

return [
  {
    json: {
      queryBody: {
        query: embedding,
        limit: 5,
        filter: {
          must: [
            {
              key: "publishedAt",
              range: {
                gte: cutoff,
                lte: now
              }
            }
          ]
        },
        with_payload: true
      }
    }
  }
];

// Input: response from Query Points
// Output: array of related docs in the old format

const results = [];
for (const point of $json.result?.points || []) {
  results.push({
    json: {
      document: {
        pageContent: point.payload.content || "",
        metadata: {
          url: point.payload.url || null,
          urlHash: point.payload.urlHash || null,
          publishedAt: point.payload.publishedAt || null
        }
      },
      score: point.score || 0
    }
  });
}

return results;

// Decide which Qdrant collection to query based on the "source" field
let collection;

if ( $('Edit Fields1').first().json.from=== "am_1st") {
  collection = "dailynews_embeddings";
} else {
  // default to news if source not explicitly "crypto_policy"
  collection = "dailynews_embeddings";
}

// Build dynamic queryUrl
return [{
  json: {
    ...$json,
    queryUrl: `https://c5b2ac61-ea4d-4482-8bed-059f617947ae.europe-west3-0.gcp.cloud.qdrant.io/collections/${collection}/points/query`
  }
}];
